/* 预设缝合神器 · 酒馆助手脚本
   用法：酒馆助手 → 脚本库 → 新建脚本 → 整段粘进去并开启。
   开启后，预设页「提示词」上方会多一条「预设缝合神器」，点开即用。
   读取：酒馆自己的预设列表（/api/settings/get）；保存：另存为新预设（/api/presets/save），绝不覆盖原预设。 */
(function () {
  'use strict';
  var P = window.parent, D = P.document;
  if (P.__pstCleanup) { try { P.__pstCleanup(); } catch (e) {} }

  /* =========================================================
     0. 小工具
     ========================================================= */
  function lsGet(k, d) { try { var v = P.localStorage.getItem('pst_' + k); return v == null ? d : JSON.parse(v); } catch (e) { return d; } }
  function lsSet(k, v) { try { P.localStorage.setItem('pst_' + k, JSON.stringify(v)); } catch (e) {} }
  function clone(o) { return JSON.parse(JSON.stringify(o)); }
  function uuid() {
    if (P.crypto && P.crypto.randomUUID) { try { return P.crypto.randomUUID(); } catch (e) {} }
    return 'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, function (c) { var r = Math.random() * 16 | 0; return (c === 'x' ? r : (r & 3 | 8)).toString(16); });
  }
  function h(tag, a, kids) {
    var e = D.createElement(tag);
    if (a) for (var k in a) {
      var v = a[k];
      if (k === 'class') e.className = v;
      else if (k === 'text') e.textContent = v;
      else if (k === 'html') e.innerHTML = v;
      else if (k === 'style') e.style.cssText = v;
      else if (k.slice(0, 2) === 'on') e.addEventListener(k.slice(2), v);
      else if (v !== false && v != null) e.setAttribute(k, v === true ? '' : v);
    }
    (kids || []).forEach(function (c) { if (c != null) e.appendChild(typeof c === 'string' ? D.createTextNode(c) : c); });
    return e;
  }
  var SVG = {
    grip: '<svg width="16" height="22" viewBox="0 0 16 22" fill="currentColor"><circle cx="4" cy="4" r="1.8"/><circle cx="12" cy="4" r="1.8"/><circle cx="4" cy="11" r="1.8"/><circle cx="12" cy="11" r="1.8"/><circle cx="4" cy="18" r="1.8"/><circle cx="12" cy="18" r="1.8"/></svg>',
    chev: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M3.5 8 L12 17 L20.5 8"/></svg>',
    plus: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M12 4v16M4 12h16"/></svg>',
    more: '<svg width="20" height="20" viewBox="0 0 24 24" fill="currentColor"><circle cx="5" cy="12" r="2"/><circle cx="12" cy="12" r="2"/><circle cx="19" cy="12" r="2"/></svg>',
    back: '<svg width="22" height="22" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round" stroke-linejoin="round"><path d="M15 4 L7 12 L15 20"/></svg>',
    undo: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round" stroke-linejoin="round"><path d="M9 7 L4 12 L9 17"/><path d="M4 12h10a6 6 0 0 1 0 12"  transform="translate(0,-5)"/></svg>',
    search: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.4" stroke-linecap="round"><circle cx="11" cy="11" r="6.5"/><path d="M16 16l5 5"/></svg>',
    close: '<svg width="20" height="20" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2.6" stroke-linecap="round"><path d="M5 5l14 14M19 5L5 19"/></svg>'
  };
  function cleanName(s) { return String(s == null ? '' : s).replace(/[\u00a0\u3000]/g, ' ').replace(/\s+/g, ' ').trim(); }

  /* =========================================================
     1. 读取 / 保存预设（走酒馆自己的接口）
     ========================================================= */
  function stCtx() { try { return P.SillyTavern.getContext(); } catch (e) { return null; } }
  async function getHeaders() {
    var c = stCtx();
    if (c && typeof c.getRequestHeaders === 'function') { try { return c.getRequestHeaders(); } catch (e) {} }
    var hd = { 'Content-Type': 'application/json' };
    try { var r = await P.fetch('/csrf-token'); var j = await r.json(); if (j && j.token) hd['X-CSRF-Token'] = j.token; } catch (e) {}
    return hd;
  }
  async function loadPresets() {
    var r = await P.fetch('/api/settings/get', { method: 'POST', headers: await getHeaders(), body: JSON.stringify({}) });
    if (!r.ok) throw new Error('读取预设失败（' + r.status + '）');
    var j = await r.json();
    var names = j.openai_setting_names || [];
    if (!Array.isArray(names)) names = Object.keys(names);
    var arr = j.openai_settings || [], map = {}, ok = [];
    names.forEach(function (n, i) {
      var o = arr[i];
      if (typeof o === 'string') { try { o = JSON.parse(o); } catch (e) { o = null; } }
      if (o && Array.isArray(o.prompts)) { map[n] = o; ok.push(n); }
    });
    return { all: names, ok: ok, map: map };
  }
  async function savePreset(name, preset) {
    var r = await P.fetch('/api/presets/save', { method: 'POST', headers: await getHeaders(), body: JSON.stringify({ apiId: 'openai', name: name, preset: preset }) });
    if (!r.ok) throw new Error('保存失败（' + r.status + '）');
    var j = {}; try { j = await r.json(); } catch (e) {}
    return (j && j.name) || name;
  }

  /* =========================================================
     2. 预设 → 编辑模型（只动 prompts 和 prompt_order，其余原样保留）
     ========================================================= */
  function buildModel(raw) {
    var src = clone(raw), prompts = src.prompts || [], orders = Array.isArray(src.prompt_order) ? src.prompt_order : [];
    var tIdx = -1, i;
    for (i = 0; i < orders.length; i++) if (orders[i] && orders[i].character_id === 100001 && Array.isArray(orders[i].order)) tIdx = i;
    if (tIdx < 0) for (i = 0; i < orders.length; i++) if (orders[i] && Array.isArray(orders[i].order) && (tIdx < 0 || orders[i].order.length > orders[tIdx].order.length)) tIdx = i;
    var byId = {};
    prompts.forEach(function (p, k) { byId[p.identifier] = { p: p, seq: k, en: p.enabled !== false, meta: null, used: false }; });
    var used = [];
    if (tIdx >= 0) {
      orders[tIdx].order.forEach(function (o) {
        var it = byId[o.identifier];
        if (!it || it.used) return;
        it.used = true; it.en = o.enabled !== false; it.meta = o; used.push(it);
      });
    } else {
      prompts.forEach(function (p) { var it = byId[p.identifier]; it.used = true; used.push(it); });
    }
    var unused = prompts.map(function (p) { return byId[p.identifier]; }).filter(function (it) { return !it.used; });
    return { src: src, tIdx: tIdx, used: used, unused: unused, seq: prompts.length };
  }
  /* 按预设在酒馆里的实际排列顺序取词条（已启用列表在前，未使用的在后） */
  function orderedPrompts(raw) {
    var m = buildModel(raw);
    return m.used.map(function (x) { return x.p; }).concat(m.unused.map(function (x) { return x.p; }));
  }
  function exportPreset() {
    var out = clone(S.src);
    var all = S.used.concat(S.unused).sort(function (a, b) { return a.seq - b.seq; });
    var keep = {};
    out.prompts = all.map(function (it) {
      var p = clone(it.p); keep[p.identifier] = 1;
      if ('enabled' in p && it.used !== false && S.used.indexOf(it) >= 0) p.enabled = it.en;
      return p;
    });
    var order = S.used.map(function (it) {
      var o = clone(it.meta || {}); o.identifier = it.p.identifier; o.enabled = it.en; return o;
    });
    if (!Array.isArray(out.prompt_order)) out.prompt_order = [];
    if (S.tIdx >= 0 && out.prompt_order[S.tIdx]) out.prompt_order[S.tIdx].order = order;
    else out.prompt_order.unshift({ character_id: 100001, order: order });
    out.prompt_order.forEach(function (po, i) {
      if (i === S.tIdx || !po || !Array.isArray(po.order)) return;
      po.order = po.order.filter(function (o) { return keep[o.identifier]; });
    });
    return out;
  }
  function newPrompt(name, content, role) {
    return { identifier: uuid(), name: name || '', enabled: true, role: role || 'system', content: content || '', marker: false, system_prompt: false,
      injection_position: 0, injection_depth: 4, injection_order: 100, injection_trigger: [], forbid_overrides: false };
  }

  /* =========================================================
     3. 主题（跟随酒馆当前主题）
     ========================================================= */
  function resolveColor(expr) {
    var t = h('div', { style: 'position:absolute;visibility:hidden;color:' + expr }); D.body.appendChild(t);
    var c = P.getComputedStyle(t).color; t.remove();
    var m = String(c).match(/[\d.]+/g) || [128, 128, 128];
    return { r: +m[0], g: +m[1], b: +m[2], a: m.length > 3 ? +m[3] : 1 };
  }
  function lum(c) { return (0.299 * c.r + 0.587 * c.g + 0.114 * c.b) / 255; }
  function mix(a, b, t) { return { r: a.r + (b.r - a.r) * t, g: a.g + (b.g - a.g) * t, b: a.b + (b.b - a.b) * t, a: 1 }; }
  function css(c) { return 'rgb(' + Math.round(c.r) + ',' + Math.round(c.g) + ',' + Math.round(c.b) + ')'; }
  function applyTheme() {
    var text = resolveColor('var(--SmartThemeBodyColor,#dcdcdc)'), tint = resolveColor('var(--SmartThemeBlurTintColor,rgba(24,24,28,.92))');
    var quote = resolveColor('var(--SmartThemeQuoteColor,#9ab)'), dark = lum(text) > 0.5;
    var base = dark ? { r: 20, g: 20, b: 24, a: 1 } : { r: 246, g: 246, b: 250, a: 1 };
    var bg = mix(base, tint, Math.min(1, tint.a)), card = mix(bg, text, 0.07), card2 = mix(bg, text, 0.15);
    var s = ROOT.style;
    s.setProperty('--bg', css(bg)); s.setProperty('--card', css(card)); s.setProperty('--card2', css(card2));
    s.setProperty('--tx', css(text)); s.setProperty('--dim', css(mix(text, bg, 0.45))); s.setProperty('--bd', css(mix(bg, text, 0.2)));
    s.setProperty('--ac', css(quote)); s.setProperty('--on', lum(quote) > 0.55 ? '#111' : '#fff');
  }

  /* =========================================================
     4. 样式
     ========================================================= */
  var CSS = '' +
  '#pst-root{position:fixed;inset:0;z-index:99990;display:none;flex-direction:column;background:var(--bg);color:var(--tx);font-size:15px;line-height:1.4;-webkit-tap-highlight-color:transparent}' +
  '#pst-root.on{display:flex}#pst-root *{box-sizing:border-box}' +
  '#pst-root button,#pst-root input,#pst-root textarea{appearance:none;-webkit-appearance:none;border:0;margin:0;padding:0;outline:0;background:none;color:inherit;font:inherit;box-shadow:none;text-shadow:none;border-radius:0}' +
  '#pst-root button{cursor:pointer;display:inline-flex;align-items:center;justify-content:center;flex:0 0 auto}' +
  '.pst-view{display:flex;flex-direction:column;flex:1;min-height:0}' +
  '.pst-hdr{display:flex;align-items:center;gap:8px;padding:calc(10px + env(safe-area-inset-top)) 12px 10px;border-bottom:1px solid var(--bd)}' +
  '.pst-ttl{flex:1;min-width:0;font-size:17px;font-weight:700;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}' +
  '#pst-root .pst-ib{width:38px;height:38px;border-radius:12px;border:1px solid var(--bd);background:var(--card)}' +
  '#pst-root .pst-ib:active,#pst-root .pst-pb:active{opacity:.7}' +
  '#pst-root .pst-ib.dis{opacity:.35;pointer-events:none}' +
  '#pst-root .pst-pb{height:38px;padding:0 14px;border-radius:12px;background:var(--ac);color:var(--on);font-weight:700;font-size:14px}' +
  '#pst-root .pst-pb.dis{opacity:.35;pointer-events:none}' +
  '#pst-root .pst-gb{height:38px;padding:0 14px;border-radius:12px;border:1px solid var(--bd);background:var(--card);font-size:14px}' +
  '.pst-body1{flex:1;min-height:0;overflow-y:auto;padding:12px 12px calc(16px + env(safe-area-inset-bottom));overscroll-behavior:contain}' +
  '.pst-sec{font-size:13px;color:var(--dim);margin:14px 4px 8px}' +
  /* 第一步 / 第二步 大标题 */
  '.pst-step{font-size:19px;font-weight:800;line-height:1.35;color:var(--ac);margin:20px 4px 10px;word-break:break-all}' +
  '.pst-step:first-child{margin-top:6px}' +
  '.pst-step small{display:block;font-size:13px;font-weight:500;color:var(--dim);margin-top:3px}' +
  '.pst-pi{display:flex;align-items:center;gap:10px;width:100%;padding:11px 12px;margin-bottom:6px;border-radius:14px;border:1px solid var(--bd);background:var(--card);text-align:left}' +
  '#pst-root .pst-pi.on{border-color:var(--ac);background:var(--card2)}#pst-root .pst-pi.dis{opacity:.35;pointer-events:none}' +
  '.pst-pi .nm{flex:1;min-width:0;word-break:break-all}.pst-pi .ct{font-size:12px;color:var(--dim)}' +
  '.pst-pi .ck{width:22px;height:22px;border-radius:50%;border:2px solid var(--bd);display:flex;align-items:center;justify-content:center;font-size:13px;font-weight:900;color:var(--on);flex:0 0 auto}' +
  '.pst-pi.on .ck{background:var(--ac);border-color:var(--ac)}.pst-pi.sq .ck{border-radius:7px}' +
  '.pst-tools{display:none;padding:8px 12px;border-bottom:1px solid var(--bd);gap:8px;align-items:center}.pst-tools.on{display:flex}' +
  '#pst-root .pst-in{flex:1;min-width:0;height:40px;padding:0 12px;border-radius:12px;background:var(--card);border:1px solid var(--bd)}' +
  '.pst-rp{display:flex;align-items:center;gap:6px;font-size:12px;color:var(--dim)}' +
  '.pst-list{flex:1;min-height:0;overflow-y:auto;position:relative;padding:2px 0 calc(40px + env(safe-area-inset-bottom));overscroll-behavior:contain}' +
  /* 词条卡片：压扁版 */
  '.pst-card{margin:5px 10px;border-radius:12px;background:var(--card);border:1px solid var(--bd);border-left:3px solid var(--ac)}' +
  '.pst-card.off .pst-top,.pst-card.off .pst-body{opacity:.55}.pst-card.unused{border-left-color:var(--dim)}' +
  '.pst-card.drag{z-index:4;box-shadow:0 10px 26px rgba(0,0,0,.5);position:relative;background:var(--card2)}' +
  '.pst-card.flash{animation:pstflash 1.4s ease-out}@keyframes pstflash{0%{box-shadow:0 0 0 3px var(--ac)}100%{box-shadow:0 0 0 0 transparent}}' +
  '.pst-top{display:flex;align-items:center;gap:4px;padding:4px 5px 4px 0}' +
  '.pst-hd{width:26px;height:32px;touch-action:none;display:flex;align-items:center;justify-content:center;color:var(--dim);cursor:grab;flex:0 0 auto}' +
  '.pst-hd svg{width:11px;height:16px}' +
  '.pst-hd.nd{opacity:.25;cursor:default}' +
  '.pst-nw{position:relative;flex:1;min-width:0}' +
  '#pst-root .pst-nm{width:100%;height:32px;padding:0 32px 0 8px;border-radius:9px;background:var(--bg);border:1px solid var(--bd);font-weight:600;font-size:14px}' +
  '.pst-nm.lk{display:flex;align-items:center;color:var(--dim);overflow:hidden;white-space:nowrap;text-overflow:ellipsis;padding-right:8px}' +
  '#pst-root .pst-v{position:absolute;right:1px;top:1px;width:30px;height:30px;border-radius:8px;color:var(--tx)}' +
  '.pst-v svg{width:16px;height:16px;transition:transform .18s}.pst-card.open .pst-v svg{transform:rotate(90deg)}' +
  '#pst-root .pst-card .pst-ib{width:30px;height:30px;border-radius:9px;font-size:14px}' +
  '.pst-card .pst-ib svg{width:15px;height:15px}' +
  '#pst-root .pst-sw{width:38px;height:22px;border-radius:11px;background:var(--card2);border:1px solid var(--bd);position:relative}' +
  '.pst-sw::after{content:"";position:absolute;top:2px;left:2px;width:16px;height:16px;border-radius:50%;background:var(--tx);opacity:.75;transition:left .15s}' +
  '#pst-root .pst-sw.on{background:var(--ac)}.pst-sw.on::after{left:18px;background:var(--on);opacity:1}' +
  '.pst-body{display:none;flex-direction:column;gap:8px;padding:0 8px 10px 10px}.pst-card.open .pst-body{display:flex}' +
  '#pst-root .pst-ta{display:block;width:100%;height:190px;resize:none;overflow-y:auto;padding:10px;border-radius:12px;background:var(--bg);border:1px solid var(--bd);font-size:14px;line-height:1.55}' +
  '.pst-role{display:flex;gap:6px}' +
  '#pst-root .pst-role button{flex:1;height:34px;border-radius:10px;border:1px solid var(--bd);background:var(--bg);font-size:13px;color:var(--dim)}' +
  '#pst-root .pst-role button.on{background:var(--ac);color:var(--on);border-color:var(--ac);font-weight:700}' +
  '.pst-lkn{padding:2px 4px 4px;font-size:13px;color:var(--dim)}' +
  '.pst-secH{margin:18px 14px 4px;font-size:13px;color:var(--dim)}' +
  '.pst-sheet{position:absolute;inset:0;background:rgba(0,0,0,.5);display:flex;align-items:flex-end;justify-content:center;z-index:6}' +
  '.pst-pan{width:100%;max-width:560px;height:78%;background:var(--bg);border:1px solid var(--bd);border-bottom:0;border-radius:20px 20px 0 0;display:flex;flex-direction:column;overflow:hidden}' +
  '.pst-ph{display:flex;align-items:center;gap:8px;padding:12px 12px 8px}.pst-ph .pst-ttl{font-size:16px}' +
  '.pst-pl{flex:1;min-height:0;overflow-y:auto;padding:4px 12px calc(14px + env(safe-area-inset-bottom));overscroll-behavior:contain}' +
  '.pst-pn{padding:0 14px 8px;font-size:12px;color:var(--dim);line-height:1.5}' +
  /* 次体词条：一个框一个名字，整行宽 */
  '.pst-ei{display:block;width:100%;text-align:left;padding:11px 14px;margin:0 0 8px;border-radius:12px;border:1px solid var(--bd);background:var(--card);cursor:pointer;word-break:break-all;line-height:1.45;-webkit-user-select:none;user-select:none}' +
  '.pst-ei:active{background:var(--card2);border-color:var(--ac)}' +
  '.pst-ei.m0{opacity:.45}.pst-ei.em{opacity:.65}' +
  '.pst-ei .en{display:block;font-size:15px;font-weight:600}' +
  '.pst-ei .es{display:block;font-size:12px;color:var(--dim);margin-top:2px}' +
  '.pst-dlg{position:absolute;inset:0;background:rgba(0,0,0,.55);display:flex;align-items:center;justify-content:center;padding:22px;z-index:8}' +
  '.pst-dc{width:100%;max-width:420px;background:var(--bg);border:1px solid var(--bd);border-radius:18px;padding:16px;display:flex;flex-direction:column;gap:12px}' +
  '.pst-dc h3{font-size:17px;margin:0}.pst-dc .msg{font-size:14px;color:var(--dim);line-height:1.6;word-break:break-all}' +
  '.pst-dr{display:flex;gap:8px;justify-content:flex-end}' +
  '.pst-menu{position:absolute;z-index:7;min-width:150px;background:var(--bg);border:1px solid var(--bd);border-radius:14px;box-shadow:0 8px 24px rgba(0,0,0,.45);padding:5px}' +
  '#pst-root .pst-menu button{display:flex;width:100%;justify-content:flex-start;padding:11px 12px;border-radius:10px;font-size:14px}#pst-root .pst-menu button.rd{color:#ff6b6b}' +
  '.pst-toast{position:absolute;left:50%;bottom:calc(70px + env(safe-area-inset-bottom));transform:translateX(-50%);background:var(--tx);color:var(--bg);padding:8px 14px;border-radius:12px;font-size:13px;z-index:9;max-width:82%;text-align:center;pointer-events:none}' +
  '.pst-err{padding:16px;color:#ff8a8a;font-size:14px;line-height:1.6;word-break:break-all}' +
  /* 预设页入口长条：撑满整行 */
  '#pst-bar,#pst-float{display:flex;align-items:center;gap:10px;cursor:pointer;color:var(--SmartThemeBodyColor);background:var(--SmartThemeBlurTintColor);border:1px solid var(--SmartThemeQuoteColor,#888);border-radius:14px;padding:14px 16px;font-weight:700;font-size:16px}' +
  '#pst-bar{box-sizing:border-box;width:100%;max-width:100%;flex:0 0 100%;align-self:stretch;margin:10px 0}' +
  '#pst-bar .arr{margin-left:auto;color:var(--SmartThemeQuoteColor)}' +
  '#pst-float{position:fixed;left:10px;bottom:90px;z-index:99980;margin:0;padding:10px 14px;font-size:14px;box-shadow:0 2px 10px rgba(0,0,0,.4)}';

  /* =========================================================
     5. 界面骨架
     ========================================================= */
  var ROOT, STYLE, BAR, FLOAT, TICK = 0;
  var DB = null;               // {all, ok, map}
  var S = null;                // 当前编辑状态
  var UI = {};                 // 编辑页 DOM 引用
  var undoStack = [];

  function setView(node) {
    closeLayers();
    var old = ROOT.querySelector('.pst-view'); if (old) old.remove();
    ROOT.insertBefore(node, ROOT.firstChild);
  }
  function closeLayers() { Array.prototype.forEach.call(ROOT.querySelectorAll('.pst-sheet,.pst-dlg,.pst-menu'), function (n) { n.remove(); }); }
  function toast(msg) {
    var t = h('div', { class: 'pst-toast', text: msg }); ROOT.appendChild(t);
    setTimeout(function () { t.remove(); }, 1900);
  }
  function dialog(title, msg, buttons, extra) {
    var kids = [h('h3', { text: title })];
    if (msg) kids.push(h('div', { class: 'msg', text: msg }));
    if (extra) kids.push(extra);
    var row = h('div', { class: 'pst-dr' });
