      if (after.all.indexOf(saved) < 0) throw new Error('保存请求成功了，但预设列表里没找到它，请到预设页面确认一下');
      S.dirty = false;
      dialog('保存成功', '已另存为「' + saved + '」。如果预设下拉里暂时没看到，刷新一下页面就有了。', [{ text: '继续编辑' }, { text: '刷新页面', primary: true, fn: function () { P.location.reload(); } }]);
    } catch (e) { dialog('保存失败', String(e && e.message || e), [{ text: '好', primary: true }]); }
  }

  /* =========================================================
     6. 入口：预设页的长条 + 兜底悬浮按钮
     ========================================================= */
  function injectBar() {
    if (D.getElementById('pst-bar')) return true;
    var a = D.getElementById('completion_prompt_manager');
    if (!a || !a.parentNode) return false;
    BAR = h('div', { id: 'pst-bar', onclick: openApp }, [h('span', { text: '🧵' }), h('span', { text: '预设缝合神器' }), h('span', { class: 'arr', text: '→' })]);
    a.parentNode.insertBefore(BAR, a); return true;
  }
  function ensureEntry() {
    var got = injectBar();
    if (got && FLOAT) { FLOAT.remove(); FLOAT = null; }
    if (!got && !FLOAT && TICK > 4) { FLOAT = h('div', { id: 'pst-float', onclick: openApp }, [h('span', { text: '🧵 预设缝合' })]); D.body.appendChild(FLOAT); }
    TICK++;
  }

  STYLE = h('style', { id: 'pst-style', text: CSS }); D.head.appendChild(STYLE);
  ROOT = h('div', { id: 'pst-root' }); D.body.appendChild(ROOT);
  var iv = setInterval(ensureEntry, 1500); ensureEntry();
  P.__pstCleanup = function () {
    clearInterval(iv);
    [ROOT, STYLE, BAR, FLOAT, D.getElementById('pst-bar'), D.getElementById('pst-float')].forEach(function (n) { if (n && n.remove) n.remove(); });
  };
  P.addEventListener('pagehide', P.__pstCleanup);
})();
